package ai.eva.android.probe;
import android.app.*;import android.content.*;import android.net.Uri;import android.os.*;import android.provider.MediaStore;import android.view.*;import org.json.*;import java.io.*;import java.nio.file.*;import java.util.concurrent.*;

/** In-process own-page verification; preserves the agent kernel process. */
final class BrowserTransfersProbe {
 static void ui(ShellActivity s,Runnable work)throws Exception{CompletableFuture<Void> f=new CompletableFuture<>();s.runOnUiThread(()->{try{work.run();f.complete(null);}catch(Exception e){f.completeExceptionally(e);}});f.get(5,TimeUnit.SECONDS);}
 static String js(BrowserWindow b,String script)throws Exception{CompletableFuture<String> f=new CompletableFuture<>();b.host.runOnUiThread(()->b.browser.evaluateJavascript(script,f::complete));return f.get(5,TimeUnit.SECONDS);}
 static void choose(BrowserWindow b)throws Exception{
  JSONObject r=new JSONObject(js(b,"(()=>{const e=document.querySelector('#chooseFile');e.scrollIntoView({block:'center'});const r=e.getBoundingClientRect();return {x:r.x+r.width/2,y:r.y+r.height/2,width:innerWidth,viewport:visualViewport?.width,scale:visualViewport?.scale}})()"));
  final long downTime=SystemClock.uptimeMillis();final float[] point=new float[2];
  ui(b.host,()->{b.browser.requestFocus();float scale=(float)(b.browser.getWidth()/r.optDouble("width"));point[0]=(float)r.optDouble("x")*scale;point[1]=(float)r.optDouble("y")*scale;MotionEvent down=MotionEvent.obtain(downTime,downTime,MotionEvent.ACTION_DOWN,point[0],point[1],0);down.setSource(InputDevice.SOURCE_TOUCHSCREEN);try{b.browser.dispatchTouchEvent(down);}finally{down.recycle();}});
  Thread.sleep(90);
  ui(b.host,()->{MotionEvent up=MotionEvent.obtain(downTime,SystemClock.uptimeMillis(),MotionEvent.ACTION_UP,point[0],point[1],0);up.setSource(InputDevice.SOURCE_TOUCHSCREEN);try{b.browser.dispatchTouchEvent(up);}finally{up.recycle();}});
  long until=SystemClock.elapsedRealtime()+3000;while(b.transfers.upload==null&&SystemClock.elapsedRealtime()<until)Thread.sleep(50);
  CompletableFuture<String> nativeUrl=new CompletableFuture<>();b.host.runOnUiThread(()->nativeUrl.complete(b.browser.getUrl()));if(b.transfers.upload==null)throw new Exception("HTML file input did not invoke chooser; nativeUrl="+nativeUrl.get(2,TimeUnit.SECONDS)+" layout="+r+" point="+point[0]+","+point[1]+" state="+js(b,"JSON.stringify({clicked:window.fixtureClicked||0,trust:window.fixtureTrusted,focused:document.hasFocus(),ready:document.readyState,element:document.elementFromPoint("+r.optDouble("x")+","+r.optDouble("y")+")?.id})"));
 }
 static void run(ShellActivity shell){new Thread(()->{JSONObject report=new JSONObject();BrowserWindow browser=null;Uri selected=null;BrowserTransfers.Transfer download=null;
  try{
   if(BrowserWindow.live!=null)throw new Exception("Close the current browser before running this own-page test");
   ui(shell,()->shell.showBrowser(new Intent()));browser=BrowserWindow.live;BrowserWindow b=browser;
   ui(shell,()->{b.browser.loadDataWithBaseURL("https://eva-browser-test.invalid/","<h1>Upload acceptance</h1><button id=chooseFile style='width:240px;height:100px' onclick=\"window.fixtureClicked=(window.fixtureClicked||0)+1;window.fixtureTrusted=event.isTrusted;document.querySelector('input').click()\">Choose file</button><input type=file accept='text/plain' style='display:none' onchange=\"this.files[0]?.text().then(t=>document.querySelector('h1').textContent=t)\">","text/html","UTF-8","https://eva-browser-test.invalid/");b.windowMode(false,false);});Thread.sleep(500);
   ContentValues values=new ContentValues();values.put(MediaStore.Downloads.DISPLAY_NAME,"EvaBrowserUpload-"+java.util.UUID.randomUUID()+".txt");values.put(MediaStore.Downloads.MIME_TYPE,"text/plain");values.put(MediaStore.Downloads.RELATIVE_PATH,"Download/EvaAcceptance");selected=shell.getContentResolver().insert(MediaStore.Downloads.EXTERNAL_CONTENT_URI,values);if(selected==null)throw new Exception("Fixture URI unavailable");try(OutputStream output=shell.getContentResolver().openOutputStream(selected)){output.write("EVA_UPLOAD_7391".getBytes("UTF-8"));}
   choose(b);Uri selection=selected;ui(shell,()->{if(b.transfers.uploadPrompt!=null)b.transfers.uploadPrompt.dismiss();BrowserTransfers.pickers.put(shell,b.transfers);if(!BrowserTransfers.onActivityResult(shell,BrowserTransfers.PICK_FILE,Activity.RESULT_OK,new Intent().setData(selection)))throw new IllegalStateException("Picker routing missing");});
   long until=SystemClock.elapsedRealtime()+5000;boolean readable=false;while(SystemClock.elapsedRealtime()<until){if("true".equals(js(b,"document.querySelector('h1').textContent==='EVA_UPLOAD_7391'"))){readable=true;break;}Thread.sleep(50);}if(!readable)throw new Exception("HTML file input could not read selected URI");report.put("upload","PASS real HTML file input reads own URI; selected URI injected into picker callback");
   js(b,"document.querySelector('input').value='';true");choose(b);ui(shell,()->{if(b.transfers.uploadPrompt!=null)b.transfers.uploadPrompt.dismiss();b.transfers.finishUpload(Activity.RESULT_CANCELED,null);});if(b.transfers.upload!=null)throw new Exception("Cancel retained upload callback");report.put("uploadCancel","PASS");choose(b);ui(shell,b.transfers::pageChanged);if(b.transfers.upload!=null)throw new Exception("Navigation retained upload callback");report.put("navigationCancel","PASS");
   BrowserTransfers.Transfer task=new BrowserTransfers.Transfer("https://example.com/",new JSONArray("["+js(b,"navigator.userAgent")+"]").getString(0),"https://example.com","https://example.com","eva-download-acceptance.html",-1);download=task;ui(shell,()->{b.transfers.items.add(0,task);b.transfers.start(task);});until=SystemClock.elapsedRealtime()+30000;while(!task.terminal()&&SystemClock.elapsedRealtime()<until)Thread.sleep(100);if(!task.state.equals("completed")){task.cancel();throw new Exception("HTTPS download failed: "+task.label());}File file=WorkspaceFiles.resolve(shell,task.path.substring("/root/eva-workspace/".length()));if(!new String(Files.readAllBytes(file.toPath()),"UTF-8").contains("Example Domain"))throw new Exception("Download content mismatch");report.put("downloadBytes",task.received).put("download","PASS HTTPS small file saved in workspace");
   BrowserTransfers.Transfer cancelled=new BrowserTransfers.Transfer("https://example.com/","","https://example.com","https://example.com","cancelled.html",-1);cancelled.cancel();ui(shell,()->b.transfers.start(cancelled));if(!cancelled.state.equals("cancelled")||cancelled.partial!=null)throw new Exception("Cancelled download started");report.put("pendingDownloadCancel","PASS");
   BrowserTransfers.Transfer activeCancel=new BrowserTransfers.Transfer("https://example.com/","","https://example.com","https://example.com","active-cancel.html",-1);ui(shell,()->{b.transfers.start(activeCancel);activeCancel.cancel();});until=SystemClock.elapsedRealtime()+5000;while(!activeCancel.terminal()&&SystemClock.elapsedRealtime()<until)Thread.sleep(50);if(!activeCancel.state.equals("cancelled")||!activeCancel.path.isEmpty()||activeCancel.partial!=null&&activeCancel.partial.exists())throw new Exception("Started download cancellation left output");report.put("startedDownloadCancel","PASS cancellation immediately after start leaves no partial output");
   FakePermission unknown=new FakePermission("https://eva-browser-test.invalid/",new String[]{"unsupported-resource"});ui(shell,()->b.sitePermissions.request(unknown));if(!unknown.denied||unknown.granted)throw new Exception("Unsupported website resource accepted");report.put("unsupportedPermission","PASS denied without granting system access");
   ui(shell,()->b.windowMode(false,true));WindowManager.LayoutParams flags=b.getWindow().getAttributes();if((flags.flags&WindowManager.LayoutParams.FLAG_NOT_FOCUSABLE)==0||(flags.flags&WindowManager.LayoutParams.FLAG_NOT_TOUCH_MODAL)==0||flags.width!=b.dp(52)||flags.height!=b.dp(52))throw new Exception("Minimized window flags or bounds changed");report.put("minimizedFlags","PASS bounded 52dp nonfocusable, nonmodal; real cross-window touch is covered separately by BrowserWindowCheck");FakePermission minimized=new FakePermission("https://eva-browser-test.invalid/",new String[]{android.webkit.PermissionRequest.RESOURCE_VIDEO_CAPTURE});ui(shell,()->b.sitePermissions.request(minimized));if(!minimized.denied||minimized.granted)throw new Exception("Minimized site acquired camera");report.put("minimizedPermission","PASS denied while minimized");report.put("result","PASS");
  }catch(Exception e){try{report.put("result","FAIL").put("error",e.toString());}catch(Exception ignored){}}
  finally{if(selected!=null)try{shell.getContentResolver().delete(selected,null,null);}catch(Exception ignored){}if(download!=null&&!download.path.isEmpty())try{File f=WorkspaceFiles.resolve(shell,download.path.substring("/root/eva-workspace/".length()));f.delete();f.getParentFile().delete();}catch(Exception ignored){}if(browser!=null){BrowserWindow b=browser;try{ui(shell,b::finish);}catch(Exception ignored){}}}
  shell.getSharedPreferences("eva-browser-check",0).edit().putString("transfers",report.toString()).commit();android.util.Log.i("EvaBrowserTransfersCheck",report.toString());
 }).start();}
 static final class FakePermission extends android.webkit.PermissionRequest {final Uri origin;final String[] resources;boolean denied,granted;FakePermission(String origin,String[] resources){this.origin=Uri.parse(origin);this.resources=resources;}public Uri getOrigin(){return origin;}public String[] getResources(){return resources;}public void grant(String[] resources){granted=true;}public void deny(){denied=true;}}
}
